const e="godtalk-nz-talent-quest",l=2019,n="Captured from the whole 2019 Godtalk Talent Quest event manual. OLD EDITION: all dates, times, fees and the evening programme are examples, kept as Variables. The manual prints NO event date or venue, NO age limits, NO marks or criteria weights, NO points, grades or ranks, NO entry limits, NO deadline and NO street address, so those stay empty or are marked to be announced. The printed contact is only the organisation's email for regional organisers; entrants send forms to an address on the regional flyer. Documents is empty because no form or score sheet link is printed. The template's two groups use placeholder ages 12 to 25 because no ages are printed.",t={Title:"Rules & Criteria",Subtitle:"Godtalk NZ Talent Quest. This is the 2019 manual, so check every date, fee and time with your regional organiser.",NoticeTitle:"Please Read Before Registering",Notice:"This page follows the 2019 manual. Dates, venue and fees are set by your regional organiser. Auditions are in the daytime and the evening is a concert with prizegiving. Venue: {{Venue}}.",Notes:["Backing tracks and videos are handed in at {{ArrivalTime}}. Registration opens {{RegistrationOpens}}.","Be ready at the side of the stage 10 minutes before your audition. There are no private green rooms."],Sections:[{Key:"general",Title:"About the Talent Quest",Items:["Godtalk Talent Quests encourage young people to use creative and cultural arts to share a Christian message in a way that suits a school or other public space.","The main aim is for youth to reach youth, by building a habit of outreach in every youth ministry.","Local youth leaders own and run their regional event. Godtalk is non-denominational and connected nationally.","The day has auditions in the daytime. The evening is a concert of selected items, with awards to category winners and a gospel message.","The daytime programme starts with a short worship and message. Short motivational talks of 2 to 4 minutes about outreach are placed between auditions.","To bring a Talent Quest to your region, send your interest to {{OrganiserContact}}."]},{Key:"eligibility",Title:"Eligibility",Items:["The manual prints no age limits, no membership rule and no limit on entries per person or group.","Entries are made as an individual performance or a group performance. A Band item is a group performance.","Non-performers may attend the daytime auditions for a fee."]},{Key:"registration",Title:"How to Register",Items:["Register online. Send your entry form to the email address on your regional organiser's flyer: {{RegistrationEmail}}.","Regional organisers create their own flyers and Facebook promotions that include that email address.","Send any lighting requests with your entry form.","Backing tracks and videos can be sent online before the day. Otherwise hand them in at {{ArrivalTime}} on a memory stick.","Original artwork: the host church contacts each entrant to arrange how the work is displayed. Talk to the organisers before the event about how to attach it to the wall."]},{Key:"fees",Title:"Fees",Items:["Individual performance: {{IndividualFee}}.","Group performance: {{GroupFee}}.","Non-performers attending in the daytime: {{VisitorFee}}.","Evening concert: {{EveningEntry}}.","The money goes toward the costs of the event."]},{Key:"dates",Title:"Dates and Times",Items:["Date of the Talent Quest: {{EventDate}}.","{{ArrivalTime}}: artwork (one hour before the start), videos and backing tracks are handed in. Registration opens {{RegistrationOpens}}.","9am: the MC welcomes everyone, explains the day and opens with a karakia (a Maori opening prayer). Worship and a short message follow.","{{AuditionsStart}}: auditions begin, in one or two rooms. The goal is to finish by 3pm or 4pm, so people can have dinner together before the evening.","Main auditorium, morning: Dance, Drama and Cultural performance. Spoken word, Gospel message and acoustic songs can be placed between items that need set-up.","12.30pm: lunch break.","Main auditorium, afternoon from 1.30pm: Band item and Original songs that use instruments.","Second auditorium, if needed, from 12.30pm: Spoken word, Gospel message and Original songs that use a backing track or are acoustic.","Auditions close at 3pm or 4pm (2pm or 4pm in the second room) with a closing karakia and a tea break.","Evening concert (example): doors open {{EveningDoors}} and the programme starts {{EveningStart}}."]},{Key:"venue",Title:"Venue",Items:["The venue is a host church. The manual says to find a church venue that you do not have to pay for.","The venue for this edition is {{Venue}}.","See the rules for each competition for instruments and lighting."]},{Key:"conduct",Title:"Conduct",Items:["Be ready at the side of the stage 10 minutes before your audition. There are no private green rooms.","Have a positive attitude toward the volunteers. Every role at the event is voluntary.","Keep props to an absolute minimum.","Every performer should feel appreciated and valued. The judges give constructive feedback, and the event aims for a fun and encouraging mood."]},{Key:"judging",Title:"Judging",Items:["All items are assessed on how well they communicate a Christian message to a public (non-church) audience, with the goal of encouraging openness to or understanding of faith in Christ.","Use at least 2 judges at a time and no more than 4. Judges are approached by the local youth leaders and serve as volunteers.","Judges should understand the art they assess, the theology and correctness of the message, and how appropriately it is communicated to a non-church audience.","The manual suggests that a full gospel message covers creation, the fall, Jesus and the wider plan of restoration, and invites a response.","The manual prints no marks, weights or score sheet."]},{Key:"points",Title:"Winners",Items:["Winners are announced during the evening programme. They are not told before.","Three finalists of each category come on stage at the prizegiving. The judges comment and a prize is given. Allow about 90 seconds per category.","The manual prints no points, grades or ranks."]},{Key:"prizes",Title:"Prizes",Items:["Prizes are decided by the organisers: {{Prizes}}.","The winner of a provincial cup keeps it for one year and defends the title the next year.","Organisers can ask local businesses for prizes and must thank the sponsors during the programme.","A photo of all winners together may be sent with a short article to local newspapers."]},{Key:"levels",Title:"Evening Concert",Items:["Organisers choose the evening items that suit the programme. They need not be only the winners.","Do not tell the performers who the winners are until the prizegiving.","Winning items can go before or after the prizegiving.","The evening has a gospel message from a guest speaker, with a response call, and ends with thanks, a closing prayer and a promotion of next year's event."]},{Key:"other",Title:"Not Part of the Competition",Items:["Worship, the opening karakia, motivational talks, testimonies, guest speakers, MC games and the evening concert are part of the programme but are not scored.","Godtalk supplies short branded video and audio clips for the MCs to use."]}],Documents:[]},a=[{ParticipantType:"Individual",Source:"Event Manual 2019 p.3",Sections:{About:null,TimeAndFormat:null,Rules:["Fee: {{IndividualFee}}."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Fee: {{IndividualFee}}.`},{ParticipantType:"Team",Source:"Event Manual 2019 p.3",Sections:{About:null,TimeAndFormat:null,Rules:["Fee: {{GroupFee}}.","The manual prints no limit on group size."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Fee: {{GroupFee}}.
- The manual prints no limit on group size.`}],o=[],i=[{Title:"Dance",Source:"Event Manual 2019 p.6",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes.","Set-up time is 2 minutes."],Rules:["Keep props to an absolute minimum.","Send any lighting requests with your entry form.","Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.","Lighting options may be very limited. Please be grateful to the volunteers, who do their best."],Allowed:null,NotAllowed:null,Judging:["Assessed on uniformity, creativity, message and costumes."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.
- Set-up time is 2 minutes.

## Rules
- Keep props to an absolute minimum.
- Send any lighting requests with your entry form.
- Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.
- Lighting options may be very limited. Please be grateful to the volunteers, who do their best.

## Judging
- Assessed on uniformity, creativity, message and costumes.`},{Title:"Drama",Source:"Event Manual 2019 p.6",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes.","Set-up time is 2 minutes."],Rules:["Keep props to an absolute minimum.","Lighting options may be very limited. Please be grateful to the volunteers, who do their best."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.
- Set-up time is 2 minutes.

## Rules
- Keep props to an absolute minimum.
- Lighting options may be very limited. Please be grateful to the volunteers, who do their best.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Spoken Word",Source:"Event Manual 2019 p.6",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes."],Rules:["The piece must be original.","If you want a backing track: Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.

## Rules
- The piece must be original.
- If you want a backing track: Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Gospel Message",Source:"Event Manual 2019 p.7",Sections:{About:null,TimeAndFormat:["Length: up to 5 minutes."],Rules:null,Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 5 minutes.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Cultural Performance",Source:"Event Manual 2019 p.7",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes."],Rules:["If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.","Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.","Lighting options may be very limited. Please be grateful to the volunteers, who do their best."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.

## Rules
- If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.
- Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.
- Lighting options may be very limited. Please be grateful to the volunteers, who do their best.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Original Song",Source:"Event Manual 2019 p.7",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes."],Rules:["The song must be original.","If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.","Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.

## Rules
- The song must be original.
- If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.
- Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Band Item",Source:"Event Manual 2019 p.7",Sections:{About:null,TimeAndFormat:["Length: up to 4 minutes."],Rules:["If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.","Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, delivery and message."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 4 minutes.

## Rules
- If you use instruments, the venue has a drum kit, bass amp, guitar amps and a keyboard. Bring your own guitars, pedals and drum sticks. The event cannot promise in-ear monitors, so use live instruments or a backing track, not both together.
- Submit backing tracks on a memory stick at 8am on the audition day, unless you sent them online before. Always keep a copy on a memory stick as a back-up.

## Judging
- Assessed on creativity, delivery and message.`},{Title:"Original Artwork",Source:"Event Manual 2019 p.8",Sections:{About:["A painting, drawing or designed graphic, displayed throughout the event."],TimeAndFormat:["Arrive with the artwork 1 hour before the audition day starts. Remove it after the evening programme ends."],Rules:["Space is limited.","Talk to the organisers before the event about how to attach the work to the wall.","The host church contacts each entrant to arrange the display."],Allowed:null,NotAllowed:null,Judging:["Judged by the people attending, on creativity and message.","Each person places one vote at the desk provided."],Points:null,Notes:null},Markdown:`## About this competition
- A painting, drawing or designed graphic, displayed throughout the event.

## Time and format
- Arrive with the artwork 1 hour before the audition day starts. Remove it after the evening programme ends.

## Rules
- Space is limited.
- Talk to the organisers before the event about how to attach the work to the wall.
- The host church contacts each entrant to arrange the display.

## Judging
- Judged by the people attending, on creativity and message.
- Each person places one vote at the desk provided.`},{Title:"Original Video",Source:"Event Manual 2019 p.8",Sections:{About:null,TimeAndFormat:["Length: up to 3 minutes."],Rules:["The video must be original. It must not be a remix of someone else's material.","Send it before the day as a YouTube link, or hand it in on a memory stick at {{ArrivalTime}}.","Keep a back-up copy on a memory stick."],Allowed:null,NotAllowed:null,Judging:["Assessed on creativity, message and potential to engage online audiences such as YouTube, Facebook and Instagram."],Points:null,Notes:null},Markdown:`## Time and format
- Length: up to 3 minutes.

## Rules
- The video must be original. It must not be a remix of someone else's material.
- Send it before the day as a YouTube link, or hand it in on a memory stick at {{ArrivalTime}}.
- Keep a back-up copy on a memory stick.

## Judging
- Assessed on creativity, message and potential to engage online audiences such as YouTube, Facebook and Instagram.`}],s=[],r=[{Key:"EventDate",Kind:"date",Label:"Date of the Talent Quest",Value:"To be announced by the regional organiser",Source:"Event Manual 2019 (no date printed)"},{Key:"Venue",Kind:"address",Label:"Host church venue",Value:{Name:"To be announced (a church venue the organisers do not pay for)",Address:"",City:"",MapUrl:"",Directions:""},Source:"Event Manual 2019 p.3"},{Key:"RegistrationEmail",Kind:"text",Label:"Email address for entry forms",Value:"The email address printed on the regional organiser's flyer",Source:"Event Manual 2019 p.3 Registrations"},{Key:"IndividualFee",Kind:"fee",Label:"Fee per individual performance",Value:"$10 per individual performance",Source:"Event Manual 2019 p.3"},{Key:"GroupFee",Kind:"fee",Label:"Fee per group performance",Value:"$20 per group performance",Source:"Event Manual 2019 p.3"},{Key:"VisitorFee",Kind:"fee",Label:"Daytime attendance for non-performers",Value:"$5 per person",Source:"Event Manual 2019 p.3"},{Key:"EveningEntry",Kind:"fee",Label:"Evening concert entry",Value:"Free, if a church venue is found that does not have to be paid for",Source:"Event Manual 2019 p.3"},{Key:"ArrivalTime",Kind:"time",Label:"Backing tracks and videos handed in",Value:"8am on audition day",Source:"Event Manual 2019 p.9"},{Key:"RegistrationOpens",Kind:"time",Label:"Registration desk opens",Value:"8am onwards",Source:"Event Manual 2019 p.9"},{Key:"AuditionsStart",Kind:"time",Label:"Auditions begin",Value:"9.30am",Source:"Event Manual 2019 p.9"},{Key:"EveningDoors",Kind:"time",Label:"Evening concert doors open",Value:"6.30pm (example programme)",Source:"Event Manual 2019 p.11"},{Key:"EveningStart",Kind:"time",Label:"Evening concert starts",Value:"7pm (example programme)",Source:"Event Manual 2019 p.11"},{Key:"OrganiserContact",Kind:"contact",Label:"Express interest in running a regional Talent Quest",Value:{Name:"Godtalk team",Role:"National organiser",Phone:"",WhatsApp:"",Email:"team@godtalk.nz"},Source:"Event Manual 2019 p.2"},{Key:"WebsiteLink",Kind:"link",Label:"Godtalk website",Value:"https://godtalk.nz",Source:"Event Manual 2019 p.2"},{Key:"Prizes",Kind:"prize",Label:"Prizes",Value:"Set by the regional organiser; the manual suggests a provincial cup for each category, kept for one year by the winner",Source:"Event Manual 2019 p.12"}],u=[{Claim:"Programme, categories, rules, fees, judging guidance, prize ideas and evening programme come from the 2019 event manual. It prints no marks, ages, deadlines or dates.",SourceType:"Primary - organiser's own manual",Source:"Godtalk Talent Quest - Event Manual 2019",Url:"https://godtalk.nz/wp-content/uploads/2019/01/GODTALK-TALENT-QUEST-PROGRAMMING-MANUEL-2019.pdf"}],d={TemplateKey:e,Year:2019,Note:n,Page:t,ParticipantTypes:a,AgeGroups:o,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:u};export{o as AgeGroups,s as CompetitionAgeGroups,i as Competitions,u as Evidence,n as Note,t as Page,a as ParticipantTypes,e as TemplateKey,r as Variables,l as Year,d as default};
